    insert into public.service_categories (id, slug, sort_order, icon, art) values ('13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 'design-creative', 0, 'PenTool', 'design');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 'az', 'Dizayn və Kreativ', 'Brendinizin vizual dili', 'Loqo və korporativ üslubdan interfeys, 3D vizualizasiya və reklam kampaniyalarına qədər — brendinizi tanınan edən vizual həllər.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 'ru', 'Дизайн и креатив', 'Визуальный язык вашего бренда', 'От логотипа и фирменного стиля до интерфейсов, 3D-визуализации и рекламных кампаний — визуальные решения, которые делают бренд узнаваемым.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 'en', 'Design & Creative', 'The visual language of your brand', 'From logos and brand identity to interfaces, 3D visualisation and campaigns — visual solutions that make your brand recognisable.');
    insert into public.service_categories (id, slug, sort_order, icon, art) values ('2449634d-5dab-4a36-baca-d0bdcf641616', 'interior-exterior-planning', 1, 'Ruler', 'space');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('2449634d-5dab-4a36-baca-d0bdcf641616', 'az', 'İnteryer, Eksteryer və Layihələndirmə', 'Məkanınız brendinizi danışsın', 'Kommersiya interyerləri, fasad və vitrin konseptləri, reklam konstruksiyalarının planlaşdırılması və istehsalat çertyojları.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('2449634d-5dab-4a36-baca-d0bdcf641616', 'ru', 'Интерьер, экстерьер и проектирование', 'Пусть пространство говорит о бренде', 'Концепции коммерческих интерьеров, фасадов и витрин, планирование рекламных конструкций и производственные чертежи.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('2449634d-5dab-4a36-baca-d0bdcf641616', 'en', 'Interior, Exterior & Planning', 'Let your space speak for your brand', 'Commercial interior, façade and shopfront concepts, advertising structure planning and production drawings.');
    insert into public.service_categories (id, slug, sort_order, icon, art) values ('7d74e31c-af06-4e8f-b362-16117ac0fb2d', 'printing-polygraphy', 2, 'Printer', 'print');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('7d74e31c-af06-4e8f-b362-16117ac0fb2d', 'az', 'Çap və Poliqrafiya', 'Vizitkartdan dev bannerə qədər', 'Vizitkart, buklet, kataloq, etiket və menyulardan banner, vinil, vitrin və divar qrafikasına qədər poliqrafiya və geniş formatlı çap.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('7d74e31c-af06-4e8f-b362-16117ac0fb2d', 'ru', 'Печать и полиграфия', 'От визитки до огромного баннера', 'Полиграфия и широкоформатная печать: от визиток, буклетов, каталогов, этикеток и меню до баннеров, винила, витринной и настенной графики.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('7d74e31c-af06-4e8f-b362-16117ac0fb2d', 'en', 'Printing & Polygraphy', 'From business cards to giant banners', 'Commercial and large-format printing: from business cards, booklets, catalogues, labels and menus to banners, vinyl, window and wall graphics.');
    insert into public.service_categories (id, slug, sort_order, icon, art) values ('0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 'advertising-production', 3, 'Factory', 'production');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 'az', 'Reklam İstehsalatı', 'İdeya fiziki formaya düşür', 'CNC, lazer və plotter kəsimi, 3D hərflər, lightbox və lövhələr, açıq hava və interyer reklam konstruksiyaları.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 'ru', 'Рекламное производство', 'Идея обретает физическую форму', 'ЧПУ, лазерная и плоттерная резка, объёмные буквы, лайтбоксы и вывески, конструкции наружной и интерьерной рекламы.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 'en', 'Advertising Production', 'Where ideas take physical form', 'CNC, laser and plotter cutting, 3D letters, lightboxes and signs, outdoor and indoor advertising structures.');
    insert into public.service_categories (id, slug, sort_order, icon, art) values ('4d44cd22-4ce1-4a39-b7fd-0cec911fd155', 'branding-promo', 4, 'Gift', 'promo');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('4d44cd22-4ce1-4a39-b7fd-0cec911fd155', 'az', 'Brendinq və Promo Məhsullar', 'Brendiniz hər yerdə yanınızda', 'Brendlənmiş hədiyyələr, korporativ geyim, DTF və flex çap, avtomobil və park brendinqi.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('4d44cd22-4ce1-4a39-b7fd-0cec911fd155', 'ru', 'Брендинг и промо-продукция', 'Ваш бренд всегда рядом', 'Брендированные подарки, корпоративная одежда, DTF и flex-печать, брендирование автомобилей и автопарков.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('4d44cd22-4ce1-4a39-b7fd-0cec911fd155', 'en', 'Branding & Promotional Products', 'Your brand, everywhere you go', 'Branded gifts, corporate apparel, DTF and flex printing, vehicle and fleet branding.');
    insert into public.service_categories (id, slug, sort_order, icon, art) values ('774bcbcd-d442-4f9f-8f90-8b3651ea29d2', 'digital-advertising', 5, 'Megaphone', 'digital');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('774bcbcd-d442-4f9f-8f90-8b3651ea29d2', 'az', 'Rəqəmsal Reklam', 'Brendiniz lentdə də seçilsin', 'Sosial media idarəçiliyi, kontent planı, kreativ kampaniyalar və rəqəmsal reklam vizualları.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('774bcbcd-d442-4f9f-8f90-8b3651ea29d2', 'ru', 'Цифровая реклама', 'Пусть бренд выделяется и в ленте', 'Ведение соцсетей, контент-план, креативные кампании и визуалы для цифровой рекламы.');
    insert into public.service_category_translations (category_id, locale, name, tagline, description) values ('774bcbcd-d442-4f9f-8f90-8b3651ea29d2', 'en', 'Digital Advertising', 'Stand out in the feed, too', 'Social media management, content planning, creative campaigns and digital advertising visuals.');
    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('92fe930e-04ed-41f2-b4e9-21a875e2378f', 'graphic-design', '13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 0, 'PenTool', array['quantity','dimensions']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('92fe930e-04ed-41f2-b4e9-21a875e2378f', 'az', 'Qrafik dizayn', 'Loqo, korporativ üslub, çap və sosial media dizaynı.', 'Brendinizi bir baxışda tanıdan dizayn.', 'Loqodan menyuya, vizitkartdan reklam kampaniyasına qədər bütün vizual materialları vahid üslubda hazırlayırıq. Dizayn faylları çapa və rəqəmsal istifadəyə hazır formatda təhvil verilir.', array['Yeni açılan kafe üçün loqo, menyu və vitrin dizaynı','Şirkət üçün vizitkart, blank və təqdimat şablonları','Məhsul xətti üçün qablaşdırma və etiketlər','Tədbir üçün poster, flayer və sosial media vizualları']::text[], '[{"q":"Dizayn faylları hansı formatda təhvil verilir?","a":"Adətən çap üçün vektor PDF/AI/EPS və rəqəmsal istifadə üçün PNG/JPG/SVG formatlarında. Lazımi formatları layihənin əvvəlində razılaşdırırıq."},{"q":"Dizaynı sonra çap da etdirə bilərəm?","a":"Bəli. Dizayn və çap bir komandada olduğu üçün maket birbaşa istehsalata hazır şəkildə hazırlanır."}]'::jsonb, 'loqo, logo, brend, korporativ stil, firma stili, vizitka, vizit kart, flayer, buklet, menyu, qablaşdırma, etiket, dizayner');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('92fe930e-04ed-41f2-b4e9-21a875e2378f', 'ru', 'Графический дизайн', 'Логотипы, фирменный стиль, дизайн для печати и соцсетей.', 'Дизайн, по которому ваш бренд узнают с первого взгляда.', 'Разрабатываем все визуальные материалы в едином стиле — от логотипа и меню до визиток и рекламных кампаний. Макеты передаются в форматах, готовых к печати и цифровому использованию.', array['Логотип, меню и оформление витрины для нового кафе','Визитки, бланки и шаблоны презентаций для компании','Упаковка и этикетки для продуктовой линейки','Постеры, флаеры и визуалы для соцсетей к мероприятию']::text[], '[{"q":"В каких форматах передаются макеты?","a":"Обычно — векторные PDF/AI/EPS для печати и PNG/JPG/SVG для цифрового использования. Нужные форматы согласовываем в начале проекта."},{"q":"Можно ли потом заказать печать по этому дизайну?","a":"Да. Дизайн и печать — в одной команде, поэтому макет сразу готовится с учётом производства."}]'::jsonb, 'логотип, лого, фирменный стиль, брендбук, визитка, флаер, буклет, меню, упаковка, этикетка, дизайнер');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('92fe930e-04ed-41f2-b4e9-21a875e2378f', 'en', 'Graphic Design', 'Logos, identity, print and social media design.', 'Design that makes your brand recognisable at a glance.', 'We create every visual asset in one consistent style — from logos and menus to business cards and campaigns. Files are delivered ready for print and digital use.', array['Logo, menu and window design for a new café','Business cards, letterheads and presentation templates for a company','Packaging and labels for a product line','Posters, flyers and social visuals for an event']::text[], '[{"q":"In which formats are design files delivered?","a":"Usually vector PDF/AI/EPS for print and PNG/JPG/SVG for digital use. We agree the required formats at the start."},{"q":"Can you also print the design?","a":"Yes. Because design and print are in one team, artwork is prepared ready for production from the start."}]'::jsonb, 'logo, brand identity, branding, business card, flyer, leaflet, menu, packaging, label, designer');
