    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('f7422411-73d5-4ea1-beaa-2f9ffc0f8251', 'ui-ux-design', '13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 1, 'MonitorSmartphone', array['platform']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('f7422411-73d5-4ea1-beaa-2f9ffc0f8251', 'az', 'UI/UX dizayn', 'Veb sayt və mobil tətbiq interfeysləri, prototiplər.', 'Rahat istifadə olunan və brendə uyğun interfeyslər.', 'İstifadəçinin yolunu planlaşdırır, wireframe və interaktiv prototiplər hazırlayır, sonra isə brendinizə uyğun vizual interfeys dizayn edirik. Hazır dizayn faylları proqramçılara təhvil verilməyə hazır olur.', array['Xidmət şirkəti üçün korporativ sayt dizaynı','Kampaniya üçün tək səhifəlik landing','Mövcud saytın müasir redizaynı','Mobil tətbiq ideyası üçün klikləmə prototipi']::text[], '[{"q":"Saytın proqramlaşdırılmasını da edirsiniz?","a":"Bu xidmət interfeys və istifadəçi təcrübəsi dizaynını əhatə edir. Proqramlaşdırma ehtiyacınızı konsultasiya zamanı ayrıca müzakirə edirik."},{"q":"Prototipi nə üçün etməliyik?","a":"Prototip strukturu və istifadə rahatlığını vizual dizayndan əvvəl yoxlamağa imkan verir — dəyişikliklər daha ucuz və sürətli olur."}]'::jsonb, 'ui, ux, sayt dizaynı, veb dizayn, web dizayn, interfeys, landing, prototip, figma, mobil tətbiq');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('f7422411-73d5-4ea1-beaa-2f9ffc0f8251', 'ru', 'UI/UX-дизайн', 'Интерфейсы сайтов и мобильных приложений, прототипы.', 'Удобные интерфейсы в стиле вашего бренда.', 'Продумываем путь пользователя, готовим wireframe и интерактивные прототипы, а затем — визуальный интерфейс в стиле бренда. Готовые макеты удобно передавать разработчикам.', array['Дизайн корпоративного сайта для сервисной компании','Одностраничный лендинг для рекламной кампании','Современный редизайн существующего сайта','Кликабельный прототип для идеи мобильного приложения']::text[], '[{"q":"Вы также занимаетесь программированием сайта?","a":"Эта услуга охватывает дизайн интерфейса и пользовательского опыта. Потребность в разработке обсуждаем отдельно на консультации."},{"q":"Зачем нужен прототип?","a":"Прототип позволяет проверить структуру и удобство до визуального дизайна — изменения обходятся дешевле и быстрее."}]'::jsonb, 'ui, ux, дизайн сайта, веб-дизайн, интерфейс, лендинг, прототип, figma, мобильное приложение');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('f7422411-73d5-4ea1-beaa-2f9ffc0f8251', 'en', 'UI/UX Design', 'Website and mobile app interfaces, prototypes.', 'Interfaces that are easy to use and true to your brand.', 'We map the user journey, build wireframes and interactive prototypes, then design a visual interface that fits your brand. Final files are ready to hand over to developers.', array['Corporate website design for a service company','Single-page landing for a campaign','Modern redesign of an existing site','Clickable prototype for a mobile app idea']::text[], '[{"q":"Do you also build the website?","a":"This service covers interface and user experience design. Development needs are discussed separately during consultation."},{"q":"Why build a prototype?","a":"A prototype lets you test structure and usability before visual design, making changes faster and cheaper."}]'::jsonb, 'ui, ux, web design, website design, interface, landing page, prototype, figma, mobile app');
