    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('58bf2627-64a7-4351-8b8b-e14dd1e08741', '3d-visualization', '13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 2, 'Box', array['dimensions']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('58bf2627-64a7-4351-8b8b-e14dd1e08741', 'az', '3D dizayn və vizualizasiya', '3D modelləşdirmə, məhsul və reklam konstruksiyası vizualları.', 'Nəticəni istehsalatdan əvvəl görün.', '3D vizualizasiya lövhənin fasadda, stendin sərgidə və ya interyerin hazır halda necə görünəcəyini əvvəlcədən göstərir. Bu, qərar qəbulunu asanlaşdırır və istehsalatda səhv riskini azaldır.', array['Mağaza fasadında lövhənin real ölçüdə görünüşü','Sərgi stendinin bütün tərəflərdən görünüşü','Kataloq və sayt üçün məhsul renderləri','Brendlənmiş ofis interyerinin konsepti']::text[], '[{"q":"Vizualizasiya üçün nə lazımdır?","a":"Məkanın foto və ölçüləri, loqo və istəkləriniz kifayətdir. Texniki çertyoj varsa, nəticə daha dəqiq olur."},{"q":"3D vizualı istehsalat üçün istifadə etmək olar?","a":"Vizualizasiya təsdiqdən sonra istehsalat çertyojlarının hazırlanması üçün əsas olur."}]'::jsonb, '3d, 3d dizayn, render, vizualizasiya, modelləşdirmə, 3d model, maket');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('58bf2627-64a7-4351-8b8b-e14dd1e08741', 'ru', '3D-дизайн и визуализация', '3D-моделирование, визуализация продуктов и рекламных конструкций.', 'Увидьте результат ещё до производства.', '3D-визуализация заранее показывает, как вывеска будет смотреться на фасаде, стенд — на выставке, а интерьер — в готовом виде. Это упрощает решения и снижает риск ошибок в производстве.', array['Вид вывески на фасаде магазина в реальном масштабе','Выставочный стенд со всех ракурсов','Рендеры продукта для каталога и сайта','Концепция брендированного офисного интерьера']::text[], '[{"q":"Что нужно для визуализации?","a":"Достаточно фото и размеров места, логотипа и пожеланий. Если есть чертежи — результат будет точнее."},{"q":"Можно ли использовать 3D-визуал для производства?","a":"После утверждения визуализация становится основой для производственных чертежей."}]'::jsonb, '3d, 3д, рендер, визуализация, моделирование, 3d модель');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('58bf2627-64a7-4351-8b8b-e14dd1e08741', 'en', '3D Design & Visualization', '3D modelling, product and signage visualisation.', 'See the result before production begins.', '3D visualisation shows in advance how a sign will look on a façade, a stand at an exhibition or an interior when complete — making decisions easier and reducing production risk.', array['A shop sign shown on the façade at real scale','An exhibition stand from every angle','Product renders for catalogues and websites','Concept for a branded office interior']::text[], '[{"q":"What do you need for a visualisation?","a":"Photos and dimensions of the space, your logo and preferences are enough. Technical drawings make the result more precise."},{"q":"Can the 3D visual be used for production?","a":"Once approved, the visualisation becomes the basis for production drawings."}]'::jsonb, '3d, render, rendering, visualisation, visualization, modelling, cgi');
