    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('c69e0a96-53a0-43bb-8ba1-21d2ba8ae38d', 'branding', '13cf5711-4e7f-4cd7-a495-1fe3e7597c1e', 3, 'Sparkles', '{}'::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('c69e0a96-53a0-43bb-8ba1-21d2ba8ae38d', 'az', 'Brendinq və kreativ konseptlər', 'Vizual kimlik, brend sistemləri və kampaniya konseptləri.', 'Tanınan brend ardıcıllıqla qurulur.', 'Brendin vizual kimliyini sistem kimi qururuq: loqo, rənglər, şriftlər, qrafik elementlər və onların lövhədən geyimə qədər bütün daşıyıcılarda tətbiqi. Kampaniya konseptləri isə bu sistemi konkret mesajlara çevirir.', array['Yeni biznes üçün tam brend paketi','Mövcud brendin yenilənməsi (rebrendinq)','Mövsümi reklam kampaniyasının konsepti','Brendin ofis, geyim və avtomobillərdə tətbiqi']::text[], '[{"q":"Brendinq ilə qrafik dizayn arasında fərq nədir?","a":"Qrafik dizayn konkret materialları yaradır, brendinq isə onların hamısının tabe olduğu vahid sistemi və qaydaları müəyyən edir."},{"q":"Brendi istehsalatda da tətbiq edirsiniz?","a":"Bəli — lövhələr, interyer reklamı, geyim, avtomobil və promo məhsullar üzərində tətbiqi bir yerdə həyata keçirə bilərik."}]'::jsonb, 'brendinq, brending, rebrendinq, vizual kimlik, korporativ üslub, kampaniya, reklam konsepti');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('c69e0a96-53a0-43bb-8ba1-21d2ba8ae38d', 'ru', 'Брендинг и креативные концепции', 'Визуальная айдентика, бренд-системы и концепции кампаний.', 'Узнаваемый бренд строится последовательно.', 'Выстраиваем визуальную идентичность бренда как систему: логотип, цвета, шрифты, графические элементы и их применение на всех носителях — от вывески до одежды. Концепции кампаний превращают эту систему в конкретные сообщения.', array['Полный бренд-пакет для нового бизнеса','Обновление существующего бренда (ребрендинг)','Концепция сезонной рекламной кампании','Применение бренда в офисе, на одежде и автомобилях']::text[], '[{"q":"Чем брендинг отличается от графического дизайна?","a":"Графический дизайн создаёт конкретные материалы, а брендинг задаёт единую систему и правила, которым они подчиняются."},{"q":"Вы применяете бренд и в производстве?","a":"Да — можем реализовать применение на вывесках, в интерьере, на одежде, автомобилях и промо-продукции."}]'::jsonb, 'брендинг, ребрендинг, айдентика, фирменный стиль, концепция кампании');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('c69e0a96-53a0-43bb-8ba1-21d2ba8ae38d', 'en', 'Branding & Creative Concepts', 'Visual identity, brand systems and campaign concepts.', 'A recognisable brand is built consistently.', 'We build your visual identity as a system: logo, colours, typefaces, graphic elements and their use on every touchpoint, from signage to apparel. Campaign concepts turn that system into specific messages.', array['A complete brand package for a new business','Refreshing an existing brand (rebranding)','Concept for a seasonal advertising campaign','Applying the brand to offices, apparel and vehicles']::text[], '[{"q":"How is branding different from graphic design?","a":"Graphic design creates specific materials; branding defines the single system and rules they all follow."},{"q":"Do you also apply the brand in production?","a":"Yes — we can roll it out on signage, interiors, apparel, vehicles and promotional products in one place."}]'::jsonb, 'branding, rebranding, identity, brand identity, campaign concept, creative concept');
    insert into public.service_items (id, service_id, sort_order) values ('b24168d9-7e91-4385-bc1e-fd8ae5d55f9c', 'c69e0a96-53a0-43bb-8ba1-21d2ba8ae38d', 0);
