    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('ca65b7f2-254a-45b4-b740-f40e94ebdff3', 'interior-design', '2449634d-5dab-4a36-baca-d0bdcf641616', 0, 'Sofa', array['dimensions']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('ca65b7f2-254a-45b4-b740-f40e94ebdff3', 'az', 'İnteryer dizaynı', 'Ofis, mağaza və şourumlar üçün brendlənmiş interyer konseptləri.', 'Brendinizin içəridən hiss olunduğu məkanlar.', 'Kommersiya məkanlarını brendin xarakterinə uyğun planlaşdırırıq: rəng, material, işıq və reklam elementlərinin yerləşdirilməsi. Konsept 3D vizualizasiya ilə təqdim olunur.', array['Ofisin qəbul zonası və divar brendinqi','Mağazada məhsul və reklam zonalarının planı','Avtomobil və ya mebel şourumu konsepti','Kafe interyerində brend elementləri']::text[], '[{"q":"Təmir işlərini də görürsünüz?","a":"Xidmətimiz interyer konsepti, vizualizasiya və reklam elementlərinin hazırlanmasını əhatə edir. Tikinti-təmir işləri ayrıca razılaşdırılır."},{"q":"Kiçik məkanlar üçün də işləyirsiniz?","a":"Bəli, kiçik ofis və ya butik üçün də konsept hazırlaya bilərik."}]'::jsonb, 'interyer, interier, ofis dizaynı, mağaza dizaynı, şourum, interyer dizayn');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('ca65b7f2-254a-45b4-b740-f40e94ebdff3', 'ru', 'Дизайн интерьера', 'Брендированные концепции интерьеров офисов, магазинов и шоурумов.', 'Пространства, где бренд ощущается изнутри.', 'Планируем коммерческие пространства в характере бренда: цвет, материалы, свет и размещение рекламных элементов. Концепция представляется в 3D-визуализации.', array['Ресепшн и брендирование стен офиса','План товарных и рекламных зон магазина','Концепция автосалона или мебельного шоурума','Элементы бренда в интерьере кафе']::text[], '[{"q":"Вы выполняете ремонтные работы?","a":"Услуга охватывает концепцию интерьера, визуализацию и изготовление рекламных элементов. Строительно-ремонтные работы обсуждаются отдельно."},{"q":"Работаете ли вы с небольшими помещениями?","a":"Да, можем подготовить концепцию и для небольшого офиса или бутика."}]'::jsonb, 'интерьер, дизайн офиса, дизайн магазина, шоурум');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('ca65b7f2-254a-45b4-b740-f40e94ebdff3', 'en', 'Interior Design', 'Branded interior concepts for offices, shops and showrooms.', 'Spaces where your brand is felt from the inside.', 'We plan commercial spaces around your brand: colour, materials, light and placement of advertising elements. Concepts are presented with 3D visualisation.', array['Office reception and wall branding','Product and advertising zones in a shop','Car or furniture showroom concept','Brand elements in a café interior']::text[], '[{"q":"Do you carry out renovation work?","a":"The service covers the interior concept, visualisation and producing advertising elements. Construction work is agreed separately."},{"q":"Do you work on small spaces?","a":"Yes, we can prepare concepts for small offices or boutiques too."}]'::jsonb, 'interior, interior design, office design, retail design, showroom');
