    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('a86cacd0-1dda-4aa4-a094-fce677db4498', 'exterior-design', '2449634d-5dab-4a36-baca-d0bdcf641616', 1, 'Building2', array['dimensions']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('a86cacd0-1dda-4aa4-a094-fce677db4498', 'az', 'Eksteryer dizaynı', 'Fasad, vitrin və giriş konseptləri, xarici brendinq.', 'İlk təəssürat küçədən başlayır.', 'Fasad, vitrin və giriş hissəsini brendin vizual sisteminə uyğun planlaşdırırıq ki, məkanınız uzaqdan seçilsin. Konseptlər 3D vizualizasiya ilə təqdim olunur və istehsalata hazır şəkildə detallaşdırılır.', array['Yeni mağazanın fasad və lövhə konsepti','Restoranın giriş hissəsi və vitrin qrafikası','Şəbəkə filialları üçün vahid fasad standartı','Biznes mərkəzinin xarici naviqasiya konsepti']::text[], '[{"q":"Fasad reklamı üçün icazə məsələlərini həll edirsiniz?","a":"İcazə tələbləri məkana görə fərqlənir. Konsultasiya zamanı hansı sənədlərin lazım ola biləcəyini müzakirə edirik; rəsmi icazələrin alınması müştəri ilə ayrıca razılaşdırılır."},{"q":"Konsepti sonra istehsal edə bilərsiniz?","a":"Bəli, lövhə, 3D hərf və vitrin qrafikası kimi elementləri istehsalat bölməmizdə hazırlayırıq."}]'::jsonb, 'eksteryer, fasad, vitrin, giriş, fasad dizaynı, fasad reklamı');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('a86cacd0-1dda-4aa4-a094-fce677db4498', 'ru', 'Дизайн экстерьера', 'Концепции фасадов, витрин и входных групп, наружный брендинг.', 'Первое впечатление начинается с улицы.', 'Планируем фасад, витрину и входную группу в соответствии с визуальной системой бренда, чтобы место было заметно издалека. Концепции показываем в 3D и детализируем для производства.', array['Концепция фасада и вывески нового магазина','Входная группа и витринная графика ресторана','Единый стандарт фасадов для сети филиалов','Концепция наружной навигации бизнес-центра']::text[], '[{"q":"Решаете ли вы вопросы разрешений на фасадную рекламу?","a":"Требования к разрешениям зависят от места. На консультации обсуждаем, какие документы могут понадобиться; получение разрешений согласовывается с клиентом отдельно."},{"q":"Можете ли вы затем изготовить по концепции?","a":"Да, вывески, объёмные буквы и витринную графику изготавливаем в нашем производстве."}]'::jsonb, 'экстерьер, фасад, витрина, входная группа, дизайн фасада');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('a86cacd0-1dda-4aa4-a094-fce677db4498', 'en', 'Exterior Design', 'Façade, shopfront and entrance concepts, external branding.', 'First impressions start on the street.', 'We plan façades, shopfronts and entrances in line with your brand system so your location stands out from afar. Concepts are shown in 3D and detailed for production.', array['Façade and sign concept for a new shop','Restaurant entrance and window graphics','A unified façade standard for a branch network','External wayfinding concept for a business centre']::text[], '[{"q":"Do you handle permits for façade advertising?","a":"Permit requirements vary by location. We discuss which documents may be needed during consultation; obtaining official permits is agreed separately with the client."},{"q":"Can you produce the concept afterwards?","a":"Yes, signs, 3D letters and window graphics are made by our production team."}]'::jsonb, 'exterior, façade, facade, shopfront, storefront, entrance');
