    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('11b946b3-5daf-4a35-9914-7aa537628504', 'project-planning', '2449634d-5dab-4a36-baca-d0bdcf641616', 2, 'Ruler', array['dimensions','installation']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('11b946b3-5daf-4a35-9914-7aa537628504', 'az', 'Layihələndirmə', 'Reklam konstruksiyalarının planı, texniki və istehsalat çertyojları.', 'Dəqiq plan — problemsiz istehsalat.', 'Reklam məhsulu istehsalata getməzdən əvvəl ölçüləri, materialları və quraşdırma ardıcıllığını planlaşdırırıq. Texniki və istehsalat çertyojları ideyanın dəqiq və təkrar oluna bilən şəkildə hazırlanmasına kömək edir.', array['Fasad lövhəsinin ölçülü sxemi','Biznes mərkəzi üçün naviqasiya lövhələri planı','CNC və lazer kəsim üçün istehsalat faylları','Sərgi stendinin montaj ardıcıllığı']::text[], '[{"q":"Bu memarlıq və ya mühəndislik layihəsidir?","a":"Xeyr. Xidmət reklam məhsullarının və konstruksiyalarının istehsalat və quraşdırma planlamasını əhatə edir. Lisenziya tələb edən memarlıq və mühəndislik layihələri bu xidmətə daxil deyil."},{"q":"Ölçünü kim götürür?","a":"Məkan ölçülərini siz göndərə bilərsiniz və ya ölçü götürülməsini konsultasiya zamanı razılaşdıra bilərik."}]'::jsonb, 'layihə, çertyoj, texniki çertyoj, ölçü, sxem, planlaşdırma, montaj planı');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('11b946b3-5daf-4a35-9914-7aa537628504', 'ru', 'Проектирование', 'Планирование рекламных конструкций, технические и производственные чертежи.', 'Точный план — производство без сюрпризов.', 'Прежде чем рекламное изделие уйдёт в производство, мы планируем размеры, материалы и порядок монтажа. Технические и производственные чертежи помогают изготовить идею точно и воспроизводимо.', array['Размерная схема фасадной вывески','План навигационных табличек для бизнес-центра','Производственные файлы для ЧПУ и лазерной резки','Порядок монтажа выставочного стенда']::text[], '[{"q":"Это архитектурное или инженерное проектирование?","a":"Нет. Услуга охватывает планирование производства и монтажа рекламных изделий и конструкций. Лицензируемое архитектурное и инженерное проектирование в неё не входит."},{"q":"Кто снимает замеры?","a":"Вы можете прислать размеры сами, либо мы договоримся о замере на консультации."}]'::jsonb, 'проект, чертёж, чертеж, технический чертёж, замер, схема, планирование монтажа');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('11b946b3-5daf-4a35-9914-7aa537628504', 'en', 'Project Planning', 'Advertising structure planning, technical and production drawings.', 'Precise planning, smooth production.', 'Before an advertising product goes into production, we plan dimensions, materials and installation sequence. Technical and production drawings make the idea precise and repeatable.', array['Dimensional layout of a façade sign','Wayfinding sign plan for a business centre','Production files for CNC and laser cutting','Installation sequence for an exhibition stand']::text[], '[{"q":"Is this architectural or engineering design?","a":"No. The service covers production and installation planning for advertising products and structures. Licensed architectural or engineering design is not included."},{"q":"Who takes the measurements?","a":"You can send the dimensions yourself, or we can arrange measuring during consultation."}]'::jsonb, 'planning, technical drawing, production drawing, measurements, layout, installation plan');
    insert into public.service_items (id, service_id, sort_order) values ('e9422afe-c526-4462-8fdc-605c9614a46a', '11b946b3-5daf-4a35-9914-7aa537628504', 0);
