    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('06039eb9-56a4-4d1a-b050-f7ee9d9b3d66', 'polygraphy', '7d74e31c-af06-4e8f-b362-16117ac0fb2d', 0, 'Printer', array['quantity','dimensions','sides','finish','material']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('06039eb9-56a4-4d1a-b050-f7ee9d9b3d66', 'az', 'Poliqrafiya', 'Vizitkart, flayer, buklet, kataloq, etiket və digər çap məhsulları.', 'Əldə tutulan brend: keyfiyyətli çap məhsulları.', 'Gündəlik biznes ehtiyacları üçün bütün çap məhsullarını hazırlayırıq. Sorğuda say, ölçü, tərəflər və istədiyiniz bitməni göstərin — material və texniki həlli birlikdə seçək.', array['Komanda üçün vizitkartlar və korporativ blanklar','Restoran üçün menyu və masaüstü kartlar','Məhsul etiketləri və stikerlər','Sərgi üçün kataloq və bukletlər']::text[], '[{"q":"Minimum sifariş sayı varmı?","a":"Minimum say məhsulun növündən asılıdır. Sorğuda istədiyiniz sayı göstərin, uyğun variantı təklif edək."},{"q":"Hazır maketim var, birbaşa çap edə bilərsiniz?","a":"Bəli. Faylı sorğuya əlavə edin; çapdan əvvəl texniki yoxlama aparıb lazım olarsa düzəliş tövsiyə edirik."}]'::jsonb, 'poliqrafiya, poligrafiya, vizitkart, vizitka, vizit kart, flayer, buklet, broşür, kataloq, menyu, stiker, etiket, dəvətnamə, təqvim, kalendar, çap');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('06039eb9-56a4-4d1a-b050-f7ee9d9b3d66', 'ru', 'Полиграфия', 'Визитки, флаеры, буклеты, каталоги, этикетки и другая печатная продукция.', 'Бренд, который можно взять в руки.', 'Изготавливаем всю печатную продукцию для повседневных задач бизнеса. Укажите в заявке тираж, размер, стороны и желаемую отделку — материал и техническое решение подберём вместе.', array['Визитки и фирменные бланки для команды','Меню и настольные карточки для ресторана','Этикетки и стикеры для продукции','Каталоги и буклеты для выставки']::text[], '[{"q":"Есть ли минимальный тираж?","a":"Минимальный тираж зависит от вида продукции. Укажите нужное количество в заявке — предложим подходящий вариант."},{"q":"У меня готовый макет — напечатаете сразу?","a":"Да. Прикрепите файл к заявке; перед печатью мы проверим макет и при необходимости посоветуем правки."}]'::jsonb, 'полиграфия, визитки, визитка, флаер, листовка, буклет, брошюра, каталог, меню, стикер, наклейка, этикетка, приглашение, календарь, печать');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('06039eb9-56a4-4d1a-b050-f7ee9d9b3d66', 'en', 'Polygraphic Printing', 'Business cards, flyers, booklets, catalogues, labels and more.', 'Your brand, in people’s hands.', 'We produce every printed item a business needs day to day. Tell us quantity, size, sides and preferred finish — we’ll choose the material and technical solution together.', array['Business cards and letterheads for the team','Menus and table cards for a restaurant','Product labels and stickers','Catalogues and booklets for an exhibition']::text[], '[{"q":"Is there a minimum order quantity?","a":"The minimum depends on the product. Tell us the quantity you need and we’ll suggest the right option."},{"q":"I have ready artwork — can you print it directly?","a":"Yes. Attach the file to your request; we check it before printing and suggest fixes if needed."}]'::jsonb, 'printing, print, business cards, flyer, leaflet, booklet, brochure, catalogue, menu, sticker, label, invitation, calendar, polygraphy');
