    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('a5e40e7a-cd3b-42f0-8645-b3306b0b9da0', 'large-format-printing', '7d74e31c-af06-4e8f-b362-16117ac0fb2d', 1, 'Maximize', array['quantity','dimensions','material','installation']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('a5e40e7a-cd3b-42f0-8645-b3306b0b9da0', 'az', 'Geniş formatlı çap', 'Banner, vinil, vitrin və divar qrafikası, tədbir fonları.', 'Böyük ölçü, aydın mesaj.', 'Küçədə, mağazada və tədbirdə diqqət çəkən geniş formatlı çap məhsulları. Sorğuda ölçü, say, istifadə yeri (daxili və ya xarici) və material üstünlüklərini göstərin.', array['Fasad və hasarlar üçün reklam bannerləri','Mağaza vitrininə yapışqanlı qrafika','Ofis divarına brend qrafikası','Konfrans üçün press wall və rollap qrafikası']::text[], '[{"q":"Banner xaricdə nə qədər davam edir?","a":"Bu, material, günəş və hava şəraitindən asılıdır. İstifadə müddətinə görə uyğun materialı konsultasiyada təklif edirik."},{"q":"Quraşdırma da edirsiniz?","a":"Tələb olunduqda quraşdırmanı ayrıca planlaşdırırıq — sorğuda bunu qeyd edin."}]'::jsonb, 'banner, baner, vinil, vinyl, oracal, plyonka, yapışqanlı, vitrin, divar qrafikası, poster, press wall, presvol, fon, geniş format, iri format');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('a5e40e7a-cd3b-42f0-8645-b3306b0b9da0', 'ru', 'Широкоформатная печать', 'Баннеры, винил, витринная и настенная графика, фоны для мероприятий.', 'Большой формат — чёткое сообщение.', 'Широкоформатная печать, которая привлекает внимание на улице, в магазине и на мероприятии. Укажите в заявке размеры, количество, место использования (внутри или снаружи) и пожелания по материалу.', array['Рекламные баннеры для фасадов и ограждений','Самоклеящаяся графика для витрины магазина','Брендированная графика на стене офиса','Пресс-волл и графика для роллапа на конференцию']::text[], '[{"q":"Сколько баннер прослужит на улице?","a":"Это зависит от материала, солнца и погодных условий. Подходящий материал под нужный срок предложим на консультации."},{"q":"Вы также монтируете?","a":"При необходимости планируем монтаж отдельно — отметьте это в заявке."}]'::jsonb, 'баннер, винил, оракал, плёнка, пленка, самоклейка, витрина, настенная графика, постер, пресс-волл, широкоформатная печать');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('a5e40e7a-cd3b-42f0-8645-b3306b0b9da0', 'en', 'Large Format Printing', 'Banners, vinyl, window and wall graphics, event backdrops.', 'Big format, clear message.', 'Large-format prints that get noticed on the street, in store and at events. Tell us sizes, quantity, where it will be used (indoor or outdoor) and material preferences.', array['Advertising banners for façades and fences','Adhesive graphics for shop windows','Brand graphics for an office wall','Press wall and roll-up graphics for a conference']::text[], '[{"q":"How long does an outdoor banner last?","a":"It depends on material, sun and weather exposure. We recommend a suitable material for your required lifespan during consultation."},{"q":"Do you also install?","a":"Where needed, installation is planned separately — just mention it in your request."}]'::jsonb, 'banner, vinyl, adhesive vinyl, window graphics, wall graphics, poster, backdrop, press wall, large format, wide format');
