    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('4c7540d6-174e-4ef7-b513-18f1b159ad2c', 'cnc-cutting', '0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 0, 'Cog', array['quantity','dimensions','material']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('4c7540d6-174e-4ef7-b513-18f1b159ad2c', 'az', 'CNC kəsim', 'Reklam hərfləri, dekorativ elementlər və lövhə komponentləri.', 'Dəqiq forma, təkrarlanan keyfiyyət.', 'CNC əsaslı kəsim reklam hərfləri, lövhə hissələri və dekorativ elementləri rəqəmsal fayl əsasında dəqiq hazırlamağa imkan verir. Material və qalınlıq layihəyə görə konsultasiyada seçilir.', array['Fasad lövhəsi üçün həcmli hərflərin hissələri','Ofis divarı üçün dekorativ loqo','Stend və vitrin üçün dekorativ panellər','Seriya şəklində təkrarlanan detallar']::text[], '[{"q":"Kəsim üçün hansı fayl lazımdır?","a":"Vektor fayl (AI, EPS, SVG, DXF və ya PDF) idealdır. Fayl yoxdursa, dizayn komandamız hazırlaya bilər."},{"q":"Hansı materialları kəsirsiniz?","a":"Material seçimi məhsulun təyinatından asılıdır. Sorğuda istəyinizi yazın, uyğun variantı konsultasiyada təsdiqləyək."}]'::jsonb, 'cnc, çpu, frezer, frez, kəsim, kesim, cnc kesim, hərf kəsimi, dekor');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('4c7540d6-174e-4ef7-b513-18f1b159ad2c', 'ru', 'ЧПУ-резка', 'Рекламные буквы, декоративные элементы и компоненты вывесок.', 'Точная форма, повторяемое качество.', 'Резка на станке с ЧПУ позволяет точно изготавливать рекламные буквы, детали вывесок и декоративные элементы по цифровому файлу. Материал и толщина подбираются на консультации.', array['Детали объёмных букв для фасадной вывески','Декоративный логотип на стену офиса','Декоративные панели для стенда и витрины','Серийные повторяющиеся детали']::text[], '[{"q":"Какой файл нужен для резки?","a":"Идеален векторный файл (AI, EPS, SVG, DXF или PDF). Если файла нет — его подготовит наша дизайн-команда."},{"q":"Какие материалы вы режете?","a":"Выбор материала зависит от назначения изделия. Напишите пожелания в заявке — подходящий вариант подтвердим на консультации."}]'::jsonb, 'чпу, cnc, фрезеровка, фрезер, резка, раскрой');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('4c7540d6-174e-4ef7-b513-18f1b159ad2c', 'en', 'CNC Cutting', 'Advertising letters, decorative elements and sign components.', 'Precise shapes, repeatable quality.', 'CNC-based cutting produces advertising letters, sign parts and decorative elements precisely from a digital file. Material and thickness are chosen per project during consultation.', array['Parts for 3D letters on a façade sign','A decorative logo for an office wall','Decorative panels for stands and windows','Repeating parts produced in series']::text[], '[{"q":"What file do you need for cutting?","a":"A vector file (AI, EPS, SVG, DXF or PDF) is ideal. If you don’t have one, our design team can prepare it."},{"q":"Which materials do you cut?","a":"Material depends on the product’s purpose. Share your preference in the request and we’ll confirm the right option during consultation."}]'::jsonb, 'cnc, routing, milling, cutting, router');
