    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('36469216-ac11-4578-891a-3ac7e280b735', 'laser-cutting', '0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 1, 'Zap', array['quantity','dimensions','material']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('36469216-ac11-4578-891a-3ac7e280b735', 'az', 'Lazer kəsim', 'Dəqiq lazer kəsimi, dekorativ formalar və fərdi yazılar.', 'İncə detallar üçün lazer dəqiqliyi.', 'Lazer kəsim incə konturlu formalar, kiçik hərflər və fərdiləşdirilmiş elementlər üçün uyğundur. Reklam komponentlərindən hədiyyə məhsullarına qədər müxtəlif tətbiqlər üçün istifadə olunur.', array['Qəbul masası üçün kiçik ölçülü loqo və yazılar','Masaüstü lövhələr və nişanlar','Hədiyyə və promo məhsullar üçün fərdi detallar','Tədbir dekorasiyası üçün formalar']::text[], '[{"q":"Lazer kəsim ilə CNC kəsim arasında fərq nədir?","a":"Hər iki üsul fərqli material və detallar üçün uyğundur. Layihənizə hansının daha uyğun olduğunu konsultasiyada tövsiyə edirik."},{"q":"Tək ədəd sifariş etmək olar?","a":"Bəli, fərdi tək məhsullar üçün də sorğu göndərə bilərsiniz."}]'::jsonb, 'lazer, lazer kəsim, lazer kesim, lazerlə kəsim, qravüra, gravür, laser');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('36469216-ac11-4578-891a-3ac7e280b735', 'ru', 'Лазерная резка', 'Точная лазерная резка, декоративные формы и индивидуальные надписи.', 'Лазерная точность для тонких деталей.', 'Лазерная резка подходит для форм с тонким контуром, мелких букв и персонализированных элементов — от рекламных деталей до подарочной продукции.', array['Небольшие логотипы и надписи для ресепшн','Настольные таблички и бейджи','Индивидуальные детали для подарков и промо','Формы для декора мероприятий']::text[], '[{"q":"Чем лазерная резка отличается от ЧПУ?","a":"Методы подходят для разных материалов и деталей. Какой лучше для вашего проекта, подскажем на консультации."},{"q":"Можно заказать один экземпляр?","a":"Да, заявку можно отправить и на единичное изделие."}]'::jsonb, 'лазер, лазерная резка, лазерная гравировка, гравировка');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('36469216-ac11-4578-891a-3ac7e280b735', 'en', 'Laser Cutting', 'Precision laser cutting, decorative shapes and custom lettering.', 'Laser precision for fine detail.', 'Laser cutting suits fine contours, small lettering and personalised elements — from advertising components to gift products.', array['Small logos and lettering for a reception desk','Desk plaques and name badges','Custom parts for gifts and promo items','Shapes for event decoration']::text[], '[{"q":"What’s the difference between laser and CNC cutting?","a":"Each suits different materials and details. We’ll recommend the right one for your project during consultation."},{"q":"Can I order a single piece?","a":"Yes, you can request single custom pieces too."}]'::jsonb, 'laser, laser cutting, laser cut, engraving');
