    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('d87f2f3e-466f-4824-bcfd-4d21b521c789', 'plotter-cutting', '0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 2, 'Scissors', array['quantity','dimensions','material']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('d87f2f3e-466f-4824-bcfd-4d21b521c789', 'az', 'Plotter kəsim', 'Vinil və stiker kəsimi, vitrin yazıları, kontur kəsimli qrafika.', 'Səliqəli kontur, təmiz yazı.', 'Plotter kəsimi yapışqanlı vinildən yazı, loqo və dekorativ qrafikanın dəqiq kəsilməsi üçündür. Vitrin, avtomobil və interyer üçün sürətli və effektiv həlldir.', array['Vitrində iş saatları və loqo','Avtomobil üçün yazı və əlaqə məlumatları','Məhsullar üçün kontur kəsimli stikerlər','Şüşə arakəsmələr üçün dekorativ qrafika']::text[], '[{"q":"Plotter kəsimi ilə çap fərqlidir?","a":"Bəli. Plotter rəngli vinildən forma kəsir; çoxrəngli şəkillər üçün isə çap və kontur kəsim birlikdə tətbiq oluna bilər."},{"q":"Yapışdırmanı siz edirsiniz?","a":"Tələb olunduqda yapışdırmanı planlaşdıra bilərik — sorğuda qeyd edin."}]'::jsonb, 'plotter, plotter kəsim, plotter kesim, vinil kəsim, stiker, nakleyka, yazı, vitrin yazısı, oracal');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('d87f2f3e-466f-4824-bcfd-4d21b521c789', 'ru', 'Плоттерная резка', 'Резка винила и стикеров, надписи на витринах, контурная графика.', 'Аккуратный контур, чистая надпись.', 'Плоттерная резка — это точная вырезка надписей, логотипов и декоративной графики из самоклеящейся плёнки. Быстрое и эффективное решение для витрин, авто и интерьера.', array['Часы работы и логотип на витрине','Надписи и контакты на автомобиль','Контурные стикеры для продукции','Декоративная графика для стеклянных перегородок']::text[], '[{"q":"Плоттерная резка отличается от печати?","a":"Да. Плоттер вырезает формы из цветной плёнки, а для многоцветных изображений можно сочетать печать и контурную резку."},{"q":"Вы сами наклеиваете?","a":"При необходимости можем запланировать поклейку — отметьте в заявке."}]'::jsonb, 'плоттер, плоттерная резка, резка винила, наклейки, стикеры, надписи на витрину, оракал');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('d87f2f3e-466f-4824-bcfd-4d21b521c789', 'en', 'Plotter Cutting', 'Vinyl and sticker cutting, window lettering, contour-cut graphics.', 'Clean contours, crisp lettering.', 'Plotter cutting precisely cuts lettering, logos and decorative graphics from adhesive vinyl — a fast, effective solution for windows, vehicles and interiors.', array['Opening hours and logo on a shop window','Lettering and contact details for a vehicle','Contour-cut stickers for products','Decorative graphics for glass partitions']::text[], '[{"q":"Is plotter cutting different from printing?","a":"Yes. A plotter cuts shapes from coloured vinyl; for full-colour images, printing and contour cutting can be combined."},{"q":"Do you apply the graphics?","a":"Where needed, we can arrange application — mention it in your request."}]'::jsonb, 'plotter, plotter cutting, vinyl cutting, stickers, decals, window lettering');
