    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('113640ac-6767-4068-aa51-89eb364a505e', 'outdoor-advertising', '0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 3, 'Signpost', array['quantity','dimensions','material','installation']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('113640ac-6767-4068-aa51-89eb364a505e', 'az', 'Açıq hava reklamı', 'Mağaza lövhələri, 3D hərflər, lightbox və fasad reklamı.', 'Küçədə seçilən brend.', 'Mağaza lövhəsindən fasad konstruksiyasına qədər açıq hava reklamını dizayndan istehsalata və quraşdırmaya qədər planlaşdırırıq. Ölçü, material və işıqlandırma həlli məkana görə konsultasiyada seçilir.', array['Yeni mağaza üçün işıqlı 3D hərflər','Kafe üçün lightbox və vitrin qrafikası','Biznes mərkəzi üçün istiqamət göstəriciləri','Şəbəkə filialları üçün vahid lövhə standartı']::text[], '[{"q":"Lövhənin qiyməti nədən asılıdır?","a":"Ölçü, material, işıqlandırma, konstruksiya və quraşdırma şəraitindən. Buna görə hər lövhə üçün fərdi təklif hazırlayırıq."},{"q":"Quraşdırmanı da edirsiniz?","a":"Tələb olunduqda quraşdırma planlaşdırılır. Sorğuda ünvanı və quraşdırma ehtiyacını qeyd edin."}]'::jsonb, 'açıq hava reklamı, acik hava reklami, lövhə, reklam lövhəsi, vıveska, viveska, 3d hərf, həcmli hərf, lightbox, laytboks, işıqlı reklam, fasad reklamı, bilbord, göstərici');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('113640ac-6767-4068-aa51-89eb364a505e', 'ru', 'Наружная реклама', 'Вывески, объёмные буквы, лайтбоксы и фасадная реклама.', 'Бренд, заметный с улицы.', 'Наружную рекламу — от вывески магазина до фасадной конструкции — планируем от дизайна до производства и монтажа. Размер, материал и подсветка подбираются под место на консультации.', array['Световые объёмные буквы для нового магазина','Лайтбокс и витринная графика для кафе','Указатели для бизнес-центра','Единый стандарт вывесок для сети филиалов']::text[], '[{"q":"От чего зависит стоимость вывески?","a":"От размера, материала, подсветки, конструкции и условий монтажа. Поэтому для каждой вывески готовим индивидуальный расчёт."},{"q":"Монтаж тоже делаете?","a":"При необходимости монтаж планируется. Укажите в заявке адрес и потребность в монтаже."}]'::jsonb, 'наружная реклама, вывеска, объёмные буквы, световые буквы, лайтбокс, световой короб, фасадная реклама, билборд, указатель');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('113640ac-6767-4068-aa51-89eb364a505e', 'en', 'Outdoor Advertising', 'Shop signs, 3D letters, lightboxes and façade signage.', 'A brand that stands out on the street.', 'From shop signs to façade structures, we plan outdoor advertising from design through production and installation. Size, material and lighting are chosen for your location during consultation.', array['Illuminated 3D letters for a new shop','Lightbox and window graphics for a café','Directional signs for a business centre','Unified sign standard across branches']::text[], '[{"q":"What does the price of a sign depend on?","a":"Size, material, lighting, structure and installation conditions. That’s why every sign gets an individual quotation."},{"q":"Do you install the signs?","a":"Installation is planned where required. Include the address and installation needs in your request."}]'::jsonb, 'outdoor advertising, signage, shop sign, 3d letters, channel letters, lightbox, illuminated sign, façade sign, billboard, wayfinding');
