    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('b48d3f4d-f6b5-4111-a925-413bcc85db86', 'interior-advertising', '0919325e-4afd-4fa3-9df7-0ccb557ae9a4', 4, 'Store', array['quantity','dimensions','material','installation']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('b48d3f4d-f6b5-4111-a925-413bcc85db86', 'az', 'İnteryer reklamı', 'Daxili lövhələr, qəbul zonası, stendlər və POS materialları.', 'Brend məkanın içində də danışır.', 'Ofis, mağaza və sərgi məkanlarında brendi və naviqasiyanı aydın edən interyer reklam həlləri: qəbul zonası brendinqindən satış nöqtəsi displeylərinə qədər.', array['Ofis qəbul zonası üçün həcmli loqo','Mağazada məhsul üçün POS displey','Sərgi üçün brendlənmiş stend','Mərtəbələr üzrə naviqasiya lövhələri']::text[], '[{"q":"Sərgi stendini tam hazırlaya bilərsiniz?","a":"Stend konsepti, 3D vizualizasiya, qrafika və reklam elementlərini bir yerdə planlaşdırırıq. Həcm və tələbləri konsultasiyada dəqiqləşdiririk."},{"q":"Mövcud interyerə uyğunlaşdırırsınız?","a":"Bəli. Məkanın foto və ölçülərini göndərin, reklam elementlərini mövcud interyerə uyğun təklif edək."}]'::jsonb, 'interyer reklamı, daxili reklam, stend, sərgi stendi, pos, displey, qəbul zonası, resepşn, ofis brendinqi, lövhə, tablo, naviqasiya');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('b48d3f4d-f6b5-4111-a925-413bcc85db86', 'ru', 'Интерьерная реклама', 'Внутренние вывески, ресепшн, стенды и POS-материалы.', 'Бренд говорит и внутри помещения.', 'Решения интерьерной рекламы, которые делают бренд и навигацию понятными в офисах, магазинах и на выставках: от брендирования ресепшн до POS-дисплеев.', array['Объёмный логотип для ресепшн офиса','POS-дисплей для товара в магазине','Брендированный стенд для выставки','Навигационные таблички по этажам']::text[], '[{"q":"Можете ли вы изготовить выставочный стенд под ключ?","a":"Планируем концепцию стенда, 3D-визуализацию, графику и рекламные элементы в одном месте. Объём и требования уточняем на консультации."},{"q":"Учитываете ли вы существующий интерьер?","a":"Да. Пришлите фото и размеры помещения — предложим элементы, вписанные в интерьер."}]'::jsonb, 'интерьерная реклама, внутренняя реклама, стенд, выставочный стенд, pos, дисплей, ресепшн, брендирование офиса, таблички, навигация');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('b48d3f4d-f6b5-4111-a925-413bcc85db86', 'en', 'Interior Advertising', 'Indoor signs, reception branding, stands and POS displays.', 'Your brand, speaking indoors.', 'Indoor advertising that makes your brand and wayfinding clear in offices, shops and exhibitions — from reception branding to point-of-sale displays.', array['3D logo for an office reception','POS display for a product in store','Branded stand for an exhibition','Floor-by-floor wayfinding signs']::text[], '[{"q":"Can you produce a complete exhibition stand?","a":"We plan the stand concept, 3D visualisation, graphics and advertising elements together. Scope and requirements are clarified during consultation."},{"q":"Do you adapt to an existing interior?","a":"Yes. Send photos and dimensions and we’ll propose elements that fit your existing interior."}]'::jsonb, 'indoor advertising, interior signage, stand, exhibition stand, pos, display, reception, office branding, wayfinding');
    insert into public.service_items (id, service_id, sort_order) values ('ad535e24-d327-4ead-a135-4ea49d4f7d0e', 'b48d3f4d-f6b5-4111-a925-413bcc85db86', 0);
