    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('9ddf77e7-0e15-43c4-bc06-52b46d389800', 'az', 'Promo məhsullar', 'Brendlənmiş qələm, dəftər, korporativ hədiyyələr və setlər.', 'Yadda qalan hədiyyələr, tanınan brend.', 'Tədbirlər, müştərilər və komanda üçün brendlənmiş məhsullar. Büdcə, say və mövzuya uyğun məhsul seçimini birlikdə edir, loqonun tətbiqini dizayndan çapa qədər planlaşdırırıq.', array['Yeni əməkdaşlar üçün welcome-pack','Konfrans iştirakçıları üçün qələm və dəftər','Bayram üçün korporativ hədiyyə setləri','Sərgi stendində paylanan promo məhsullar']::text[], '[{"q":"Hansı məhsullar seçmək olar?","a":"Seçim büdcə və saydan asılıdır. Sorğuda məqsədi və təxmini sayı yazın, uyğun variantlar təklif edək."},{"q":"Loqo dizaynını da edirsiniz?","a":"Bəli, loqonun məhsul üzərində düzgün yerləşdirilməsi üçün maket hazırlayırıq."}]'::jsonb, 'promo, promo məhsul, suvenir, hədiyyə, korporativ hədiyyə, brendli qələm, dəftər, bloknot, merch, merç, giveaway');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('9ddf77e7-0e15-43c4-bc06-52b46d389800', 'ru', 'Промо-продукция', 'Брендированные ручки, блокноты, корпоративные подарки и наборы.', 'Запоминающиеся подарки, узнаваемый бренд.', 'Брендированная продукция для мероприятий, клиентов и команды. Вместе подбираем изделия под бюджет, тираж и тему и планируем нанесение логотипа от дизайна до печати.', array['Welcome-pack для новых сотрудников','Ручки и блокноты для участников конференции','Праздничные корпоративные подарочные наборы','Промо-продукция для раздачи на выставке']::text[], '[{"q":"Какие изделия можно выбрать?","a":"Выбор зависит от бюджета и тиража. Опишите цель и примерное количество — предложим варианты."},{"q":"Вы делаете и дизайн нанесения?","a":"Да, готовим макет, чтобы логотип правильно разместился на изделии."}]'::jsonb, 'промо, сувениры, сувенирная продукция, подарки, корпоративные подарки, ручки с логотипом, блокноты, мерч');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('9ddf77e7-0e15-43c4-bc06-52b46d389800', 'en', 'Promotional Merchandise', 'Branded pens, notebooks, corporate gifts and sets.', 'Memorable gifts, recognisable brand.', 'Branded products for events, clients and teams. We choose items to fit your budget, quantity and theme, and plan logo application from design to print.', array['Welcome packs for new employees','Pens and notebooks for conference attendees','Holiday corporate gift sets','Giveaways for an exhibition stand']::text[], '[{"q":"Which products can I choose?","a":"It depends on budget and quantity. Describe the purpose and approximate number and we’ll suggest options."},{"q":"Do you prepare the logo artwork?","a":"Yes, we prepare artwork so the logo sits correctly on each product."}]'::jsonb, 'promo, merchandise, merch, swag, gifts, corporate gifts, branded pens, notebooks, giveaways, souvenirs');
