    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('440c3691-a3cd-44c9-a5a9-4d337cd52d93', 'clothing-branding', '4d44cd22-4ce1-4a39-b7fd-0cec911fd155', 1, 'Shirt', array['garmentType','quantity','printPlacement','sizes']::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('440c3691-a3cd-44c9-a5a9-4d337cd52d93', 'az', 'Geyim brendinqi', 'DTF və flex çap, korporativ forma, T-shirt və hudilər.', 'Komandanız brendinizin daşıyıcısıdır.', 'Korporativ forma, iş geyimi və tədbir geyimləri üzərində loqo və qrafikaların tətbiqi. Sorğuda geyim növünü, sayı, çap yerini və ölçü bölgüsünü göstərin.', array['Kafe və restoran personalı üçün forma','Marafon və ya festival üçün T-shirtlər','Tikinti şirkəti üçün iş geyimi brendinqi','Komanda üçün brendlənmiş hudilər']::text[], '[{"q":"DTF və flex çap arasında fərq nədir?","a":"DTF çoxrəngli və detallı təsvirlər üçün, flex isə sadə formalı, az rəngli loqo və yazılar üçün daha uyğundur. Layihənizə uyğun üsulu tövsiyə edirik."},{"q":"Geyimi siz təmin edirsiniz, yoxsa mən gətirməliyəm?","a":"Hər iki variant mümkündür — sorğuda qeyd edin, birlikdə ən uyğununu seçək."}]'::jsonb, 'dtf, dtf çap, flex, fleks, forma, korporativ forma, futbolka, tişört, t-shirt, hudi, hoodie, iş geyimi, geyim çapı, tekstil');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('440c3691-a3cd-44c9-a5a9-4d337cd52d93', 'ru', 'Брендирование одежды', 'DTF и flex-печать, корпоративная форма, футболки и худи.', 'Ваша команда — носитель бренда.', 'Нанесение логотипов и графики на корпоративную форму, спецодежду и одежду для мероприятий. Укажите в заявке тип одежды, количество, место нанесения и размерную сетку.', array['Форма для персонала кафе и ресторана','Футболки для марафона или фестиваля','Брендирование спецодежды строительной компании','Брендированные худи для команды']::text[], '[{"q":"Чем DTF отличается от flex-печати?","a":"DTF лучше подходит для многоцветных и детализированных изображений, flex — для простых логотипов и надписей в один-два цвета. Подскажем подходящий метод."},{"q":"Одежду предоставляете вы или мне привезти свою?","a":"Возможны оба варианта — отметьте в заявке, выберем лучший вместе."}]'::jsonb, 'dtf, dtf печать, флекс, flex, форма, корпоративная форма, футболки, худи, спецодежда, печать на одежде, текстиль');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('440c3691-a3cd-44c9-a5a9-4d337cd52d93', 'en', 'Clothing Branding', 'DTF and flex printing, uniforms, T-shirts and hoodies.', 'Your team carries your brand.', 'Applying logos and graphics to uniforms, workwear and event apparel. Include garment type, quantity, print placement and size breakdown in your request.', array['Uniforms for café and restaurant staff','T-shirts for a marathon or festival','Workwear branding for a construction company','Branded hoodies for a team']::text[], '[{"q":"What’s the difference between DTF and flex printing?","a":"DTF suits multi-colour, detailed images; flex suits simple logos and lettering in few colours. We’ll recommend the right method."},{"q":"Do you supply garments or should I bring my own?","a":"Both are possible — mention it in your request and we’ll choose together."}]'::jsonb, 'dtf, dtf printing, flex, heat transfer, uniforms, t-shirts, hoodies, workwear, apparel printing, textile');
