    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('4f781bd0-3242-46c4-920c-484669210822', 'az', 'Avtomobil brendinqi', 'Avtomobil qrafikası, yazılar, qismən və tam üzləmə konseptləri.', 'Hər gün şəhərdə hərəkət edən reklam.', 'Şirkət avtomobilləri və nəqliyyat parkı üçün yazı, loqo və qrafik dizayn. Sorğuda nəqliyyat növünü və təxmini örtük dərəcəsini göstərin — dizaynı avtomobilin formasına uyğun hazırlayırıq.', array['Çatdırılma furqonları üçün vahid dizayn','Xidmət avtomobilində loqo və əlaqə məlumatları','Kampaniya dövrü üçün promo qrafika','Taksi və ya kuryer parkı brendinqi']::text[], '[{"q":"Qrafika avtomobilin boyasına zərər verirmi?","a":"Material seçimi və düzgün tətbiq vacibdir. Avtomobilin vəziyyətini və istifadə müddətini nəzərə alaraq uyğun həlli konsultasiyada müzakirə edirik."},{"q":"Bir neçə avtomobil üçün eyni dizayn olarmı?","a":"Bəli, park üçün dizaynı müxtəlif modellərə uyğunlaşdıra bilərik."}]'::jsonb, 'avtomobil brendinqi, avtomobil üzləmə, avto üzləmə, maşın üzləmə, maşın reklamı, avto reklam, vinil, park brendinqi, furqon');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('4f781bd0-3242-46c4-920c-484669210822', 'ru', 'Брендирование автомобилей', 'Графика на авто, надписи, частичная и полная оклейка.', 'Реклама, которая каждый день ездит по городу.', 'Надписи, логотипы и графика для служебных автомобилей и автопарков. Укажите в заявке тип транспорта и примерную площадь оклейки — подготовим дизайн с учётом формы авто.', array['Единый дизайн для фургонов доставки','Логотип и контакты на служебном авто','Промо-графика на период кампании','Брендирование таксопарка или курьерского автопарка']::text[], '[{"q":"Не повредит ли графика лакокрасочное покрытие?","a":"Важны выбор материала и правильное нанесение. Подходящее решение с учётом состояния авто и срока использования обсуждаем на консультации."},{"q":"Можно ли один дизайн для нескольких авто?","a":"Да, адаптируем дизайн под разные модели автопарка."}]'::jsonb, 'брендирование авто, оклейка авто, оклейка автомобиля, реклама на авто, брендирование автопарка, наклейки на авто');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('4f781bd0-3242-46c4-920c-484669210822', 'en', 'Vehicle Branding', 'Vehicle graphics, lettering, partial and full wrap concepts.', 'Advertising that moves through the city every day.', 'Lettering, logos and graphics for company vehicles and fleets. Tell us the vehicle type and approximate coverage — we design around the shape of the vehicle.', array['Unified design for delivery vans','Logo and contact details on a service car','Promotional graphics for a campaign period','Branding for a taxi or courier fleet']::text[], '[{"q":"Will the graphics damage the paint?","a":"Material choice and correct application matter. We discuss the right solution for your vehicle’s condition and intended duration during consultation."},{"q":"Can several vehicles share one design?","a":"Yes, we can adapt one design across different fleet models."}]'::jsonb, 'vehicle branding, car wrap, vehicle wrap, car graphics, fleet branding, van lettering, car advertising');
