    insert into public.services (id, slug, category_id, sort_order, icon, quote_fields) values ('bd3f5efa-2327-4fd9-a2ad-4942ce8005be', 'social-media-marketing', '774bcbcd-d442-4f9f-8f90-8b3651ea29d2', 0, 'Megaphone', '{}'::text[]);
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('bd3f5efa-2327-4fd9-a2ad-4942ce8005be', 'az', 'Sosial media marketinqi (SMM)', 'Sosial media idarəçiliyi, dizayn, kontent planı və kampaniyalar.', 'Ardıcıl, tanınan və canlı sosial media.', 'Brendinizin sosial mediada vahid vizual dildə və planlı şəkildə danışmasına kömək edirik: kontent planı, post və story dizaynı, kreativ kampaniyalar və reklam vizualları.', array['Instagram səhifəsi üçün aylıq kontent planı və dizayn','Açılış və ya endirim kampaniyası üçün vizual seriya','Brend üçün vahid post və story şablonları','Reklam kampaniyaları üçün kreativ bannerlər']::text[], '[{"q":"Ödənişli reklamın idarə olunması daxildirmi?","a":"Xidmət kontent, dizayn və reklam kreativlərinin hazırlanmasını əhatə edir. Ödənişli reklam kampaniyalarının idarə olunması ehtiyacını ayrıca müzakirə edirik."},{"q":"Hansı platformalarla işləyirsiniz?","a":"Əsasən Instagram və Facebook. Digər platformalar üçün ehtiyacınızı sorğuda qeyd edin."}]'::jsonb, 'smm, sosial media, instagram, facebook, kontent, kontent plan, post dizaynı, story, reklam kreativi, tiktok');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('bd3f5efa-2327-4fd9-a2ad-4942ce8005be', 'ru', 'SMM — продвижение в соцсетях', 'Ведение соцсетей, дизайн, контент-план и кампании.', 'Последовательные, узнаваемые и живые соцсети.', 'Помогаем бренду говорить в соцсетях единым визуальным языком и по плану: контент-план, дизайн постов и сторис, креативные кампании и рекламные визуалы.', array['Ежемесячный контент-план и дизайн для Instagram','Серия визуалов для открытия или акции','Единые шаблоны постов и сторис для бренда','Креативные баннеры для рекламных кампаний']::text[], '[{"q":"Входит ли ведение платной рекламы?","a":"Услуга охватывает контент, дизайн и рекламные креативы. Потребность в ведении платных кампаний обсуждаем отдельно."},{"q":"С какими платформами вы работаете?","a":"В основном Instagram и Facebook. Для других платформ укажите потребность в заявке."}]'::jsonb, 'smm, смм, соцсети, инстаграм, instagram, контент, контент-план, дизайн постов, сторис, креативы');
    insert into public.service_translations (service_id, locale, title, short, headline, intro, applications, faq, keywords) values ('bd3f5efa-2327-4fd9-a2ad-4942ce8005be', 'en', 'Social Media Marketing', 'Social media management, design, content planning and campaigns.', 'Consistent, recognisable, lively social media.', 'We help your brand speak on social media with one visual language and a clear plan: content planning, post and story design, creative campaigns and ad visuals.', array['Monthly content plan and design for Instagram','A visual series for a launch or sale campaign','Unified post and story templates for a brand','Creative banners for ad campaigns']::text[], '[{"q":"Is paid ad management included?","a":"The service covers content, design and ad creatives. Managing paid campaigns is discussed separately."},{"q":"Which platforms do you work with?","a":"Mainly Instagram and Facebook. Let us know in your request if you need other platforms."}]'::jsonb, 'smm, social media, instagram, facebook, content, content plan, post design, stories, ad creatives');
