    insert into public.faq_items (id, sort_order) values ('f393f59b-1cf5-447f-b033-1815fb0aa440', 0);
    insert into public.faq_translations (faq_id, locale, question, answer) values ('f393f59b-1cf5-447f-b033-1815fb0aa440', 'az', 'Qiymətləri saytda niyə görmürəm?', 'Reklam məhsulunun qiyməti ölçü, material, say, bitmə və quraşdırma şəraitindən asılıdır. Buna görə hər sorğu üçün fərdi qiymət təklifi hazırlayırıq.'), ('f393f59b-1cf5-447f-b033-1815fb0aa440', 'ru', 'Почему на сайте нет цен?', 'Стоимость рекламного изделия зависит от размера, материала, тиража, отделки и условий монтажа. Поэтому на каждую заявку мы готовим индивидуальный расчёт.'), ('f393f59b-1cf5-447f-b033-1815fb0aa440', 'en', 'Why are there no prices on the website?', 'The price of an advertising product depends on size, material, quantity, finish and installation conditions, so we prepare an individual quotation for every request.');
    insert into public.faq_items (id, sort_order) values ('036de9d7-b89a-4f2b-a0ee-370ec62a44c8', 1);
    insert into public.faq_translations (faq_id, locale, question, answer) values ('036de9d7-b89a-4f2b-a0ee-370ec62a44c8', 'az', 'Hazır dizaynım yoxdur. Kömək edə bilərsiniz?', 'Bəli. Dizayn komandamız ideyanızı sıfırdan vizuala çevirə, sonra isə istehsalata hazırlaya bilər.'), ('036de9d7-b89a-4f2b-a0ee-370ec62a44c8', 'ru', 'У меня нет готового дизайна. Поможете?', 'Да. Наша дизайн-команда превратит идею в визуал с нуля и подготовит его к производству.'), ('036de9d7-b89a-4f2b-a0ee-370ec62a44c8', 'en', 'I don''t have a design. Can you help?', 'Yes. Our design team can turn your idea into a visual from scratch and prepare it for production.');
    insert into public.faq_items (id, sort_order) values ('ed994dfb-a2ce-4397-a3d0-e247e21fcd9f', 2);
    insert into public.faq_translations (faq_id, locale, question, answer) values ('ed994dfb-a2ce-4397-a3d0-e247e21fcd9f', 'az', 'Hansı fayl formatlarını qəbul edirsiniz?', 'Sorğu formasında PDF, JPG, PNG, SVG, AI, EPS, PSD və ZIP fayllarını yükləyə bilərsiniz. Çap üçün vektor formatlar (AI, EPS, PDF, SVG) daha yaxşı nəticə verir.'), ('ed994dfb-a2ce-4397-a3d0-e247e21fcd9f', 'ru', 'Какие форматы файлов вы принимаете?', 'В форме заявки можно загрузить PDF, JPG, PNG, SVG, AI, EPS, PSD и ZIP. Для печати лучше векторные форматы (AI, EPS, PDF, SVG).'), ('ed994dfb-a2ce-4397-a3d0-e247e21fcd9f', 'en', 'Which file formats do you accept?', 'You can upload PDF, JPG, PNG, SVG, AI, EPS, PSD and ZIP files in the request form. Vector formats (AI, EPS, PDF, SVG) give the best print results.');
    insert into public.faq_items (id, sort_order) values ('4b5c5363-f569-42bb-85ad-513eb75d0795', 3);
    insert into public.faq_translations (faq_id, locale, question, answer) values ('4b5c5363-f569-42bb-85ad-513eb75d0795', 'az', 'Sifariş nə qədər vaxt aparır?', 'Müddət məhsulun növündən, sayından və dizayn mərhələsindən asılıdır. İstədiyiniz tarixi sorğuda göstərin — real müddəti qiymət təklifi ilə birlikdə bildirəcəyik.'), ('4b5c5363-f569-42bb-85ad-513eb75d0795', 'ru', 'Сколько времени занимает заказ?', 'Срок зависит от вида изделия, тиража и этапа дизайна. Укажите желаемую дату в заявке — реальный срок сообщим вместе с расчётом.'), ('4b5c5363-f569-42bb-85ad-513eb75d0795', 'en', 'How long does an order take?', 'Timing depends on the product, quantity and design stage. Add your preferred date to the request and we will confirm a realistic timeline with the quotation.');
    insert into public.faq_items (id, sort_order) values ('3544b1bc-2d54-4ec4-b55f-1f88289b86b4', 4);
    insert into public.faq_translations (faq_id, locale, question, answer) values ('3544b1bc-2d54-4ec4-b55f-1f88289b86b4', 'az', 'Quraşdırma xidməti göstərirsiniz?', 'Lövhə və reklam konstruksiyaları kimi məhsullar üçün quraşdırma tələb olunduqda ayrıca planlaşdırılır. Sorğuda ünvanı və quraşdırma ehtiyacını qeyd edin.'), ('3544b1bc-2d54-4ec4-b55f-1f88289b86b4', 'ru', 'Вы выполняете монтаж?', 'Для вывесок и рекламных конструкций монтаж при необходимости планируется отдельно. Укажите в заявке адрес и потребность в монтаже.'), ('3544b1bc-2d54-4ec4-b55f-1f88289b86b4', 'en', 'Do you provide installation?', 'For products such as signs and advertising structures, installation is planned separately where needed. Include the address and installation needs in your request.');
    insert into public.faq_items (id, sort_order) values ('f7cb8bd7-bbc8-4a50-a6c6-0f485e343921', 5);
    insert into public.faq_translations (faq_id, locale, question, answer) values ('f7cb8bd7-bbc8-4a50-a6c6-0f485e343921', 'az', 'Sorğu göndərdikdən sonra nə baş verir?', 'Sorğu nömrəsi alırsınız, komandamız isə detalları nəzərdən keçirib seçdiyiniz üsulla — zəng, WhatsApp və ya e-poçtla — əlaqə saxlayır.'), ('f7cb8bd7-bbc8-4a50-a6c6-0f485e343921', 'ru', 'Что происходит после отправки заявки?', 'Вы получаете номер заявки, а наша команда изучает детали и связывается с вами выбранным способом — звонком, в WhatsApp или по почте.'), ('f7cb8bd7-bbc8-4a50-a6c6-0f485e343921', 'en', 'What happens after I send a request?', 'You receive a request number, and our team reviews the details and contacts you by your chosen method — phone, WhatsApp or email.');
